/**
     * Ermittelt das Zugriffslevel des angemeldeten Nutzers
     * @return int
     */
    public static function getCurrentUserAccessLevel(): int
    {
        if (MemberShip::$currentUserAccessLevel === -1) {
            MemberShip::$currentUserAccessLevel = 0;  // Default = 0, keinen Backendzugriff
            // Sitzungdaten ermitteln (Login-Status und UserId)
            $loggedIn = MemberShip::getSessionVar(self::SESSION_VAR_IS_LOGGED_IN);
            $userId = (int)MemberShip::getSessionVar(self::SESSION_VAR_USER_ID);
            if ($loggedIn && $userId > 0) {
                // User-AccessLevel frisch aus Datenbank auslesen, falls Nutzer vorhanden
                $data = MemberShip::getCurrentUserData();
                if ($data) {
                    MemberShip::$currentUserAccessLevel = (int)$data['access_level'];
                } else {
                    // Nutzer existiert nicht mehr in der DB -> Session ungültig
                    MemberShip::logoutSilently();
                }
            }
        }
        return MemberShip::$currentUserAccessLevel;
    }

    /**
     * Gibt die Id des aktuell angemeldeten Nutzers zurück
     * @return int 0 = Nutzer nicht gefunden
     */
    public static function getCurrentUserId(): int
    {
        // Sitzungsdaten ermitteln (Login-Status und UserId)
        $loggedIn = MemberShip::getSessionVar(self::SESSION_VAR_IS_LOGGED_IN);
        $user_id = (int)MemberShip::getSessionVar(self::SESSION_VAR_USER_ID);
        if ($loggedIn && $user_id) {
            return $user_id;
        } else {
            return 0;
        }
    }

    /**
     * Ermitteln die Ordnungsnummer der Dienststelle des aktuell angemeldeten Nutzers.
     * Wenn leere Zeichenkette, dann gibt es keine DienstStelle, z.B. Redakteure R1 haben keine.
     * @return ?string
     */
    public static function getCurrentDienstStelleNummer(): ?string
    {
        $data = MemberShip::getCurrentUserData();
        if ($data) {
            return $data['dienststelle'];
        } else {
            return '';
        }
    }

    /**
     * Versucht den Nutzer mit übergebenen Benutzername und Passwort einzuloggen.
     * @param string $userName Benutzername
     * @param string $userPass Passwort
     * @return bool true = Login erfolgreich, false = Login  fehlgeschlagen
     */
    public static function tryLogin(string $userName, string $userPass): bool
    {
        $loginOk = false;

        // BCRYPT-verschlüsseltes Passwort aus Datenbank lesen
        $sql = "SELECT `id`,`password`,`ldap`,`email` FROM user WHERE user_name = :userName AND `access_level` > 0";
        $statement = Page::db()->prepare($sql);
        $statement->bindValue(':userName', $userName, \PDO::PARAM_STR);

        if ($statement->execute()) {
            $result = $statement->fetch();
            if ($result) {
                $isLdapUser = (bool)$result['ldap'];

                if ($isLdapUser) {
                    // für das globale Verzeichnis des THLV müssen wir den
                    // richtigen User über die Email authentifizieren, da diese eineindeutig ist
                    // der username aber unter Umständen nicht
                    $email = $result['email'];

                    // Der Login ist nur ok, wenn
                    // - ein User genau mit dieser Email gefunden wird
                    // - der per ldap-bind sein passwort verifiziert
                    $ldapUtility = LdapUtility::getInstance();
                    $loginOk = $ldapUtility->connect() && $ldapUtility->bind() && $ldapUtility->validateUser(
                        $email,
                        $userPass
                    );

                    $ldapUtility->disconnect();
                } elseif (password_verify($userPass, $result['password'])) {
                    $loginOk = true;
                }

                if ($loginOk) {
                    MemberShip::setSessionVar(self::SESSION_VAR_IS_LOGGED_IN, true);
                    MemberShip::setSessionVar(self::SESSION_VAR_USER_ID, (int)$result['id']);

                    return $loginOk;
                }
            }
        } else {
            $errInfo = $statement->errorInfo();
            die("DB-Fehler: " . $errInfo[0] . " | " . $errInfo[1] . "\nFehlermeldung: " . $errInfo[2] . "\nSQL-Anweisung: " . $statement->queryString . "\n\n");
        }
        return $loginOk;
    }

    /**
     * Aktuellen Nutzer ausloggen. Sitzungdaten werden zurückgesetzt
     * Redirect auf Page::$config['url']['afterLogout']
     */
    public static function logout()
    {
        MemberShip::logoutSilently();
        Page::redirectLocal(Page::$config['url']['afterLogout']);
    }
